			cycle5MinusBaselineRssMiB: (settled[4].rss - baseline.rss) / mib,
			cycle5MinusBaselineHeapUsedMiB: (settled[4].heapUsed - baseline.heapUsed) / mib,
			cycle5MinusBaselineHeapSizeMiB: (settled[4].heapSize - baseline.heapSize) / mib,
			...(plateau ? {
				cycle15MinusCycle10RssMiB: (settled[14].rss - settled[9].rss) / mib,
				cycle15MinusCycle10HeapUsedMiB: (settled[14].heapUsed - settled[9].heapUsed) / mib,
				cycle15MinusBaselineRssMiB: (settled[14].rss - baseline.rss) / mib,
				cycle15MinusBaselineHeapUsedMiB: (settled[14].heapUsed - baseline.heapUsed) / mib,
			} : {}),
		};
		await Bun.write(path.join(receiptDir, receiptPrefix ? `${receiptPrefix}-summary.json` : "summary.json"), JSON.stringify(summary, null, 2));
		if (snapshots.length === 2) {
			const before = snapshots[0].classes;
			const after = snapshots[1].classes;
			const diff = Object.keys(after).map(name => ({
				name, countDelta: after[name].count - (before[name]?.count ?? 0),
				byteDelta: after[name].bytes - (before[name]?.bytes ?? 0),
			})).sort((a, b) => b.byteDelta - a.byteDelta);
			await Bun.write(path.join(receiptDir, "snapshot-diff.json"), JSON.stringify({ before: snapshots[0].at, after: snapshots[1].at, diff }, null, 2));
		}
		expect(fetchSpy.mock.calls.length).toBe(0);
		console.log(JSON.stringify({ summary: { ...summary, baseline: undefined, settled: undefined } }));
	} finally {
		await main?.suspendRpcSocket();
		main?.stop();
		await mainFixture?.close();
		await surfaces?.dispose();
		bus.clear();
		await output.close();
		await trace.close();
		await resetPaneRelay();
		vi.restoreAllMocks();
		resetSettingsForTest();
	}
}, 1_200_000);

reproductionSources.snapshotSummarizer:
interface V8Snapshot {
	snapshot: { meta: { node_fields: string[]; node_types: Array<string[] | string>; edge_fields: string[]; edge_types: Array<string[] | string> }; node_count: number; edge_count: number };
	nodes: number[];
	edges: number[];
	strings: string[];
}
interface Aggregate { count: number; bytes: number }
interface PathEntry { node: string; edge?: string }
export interface SnapshotSummary {
	at: string;
	stage: string;
	nodeCount: number;
	edgeCount: number;
	classes: Record<string, Aggregate>;
	largest: Array<{ node: string; bytes: number; path: PathEntry[] }>;
}

/** Summarize in memory: never persist raw snapshot strings or arbitrary property values. */
export function summarizeSnapshot(stage: string): SnapshotSummary {
	// Bun owns this documented V8 format; the metadata below resolves all field offsets.
	const snapshot: V8Snapshot = JSON.parse(Bun.generateHeapSnapshot("v8"));
	const meta = snapshot.snapshot.meta;
	const nodeStride = meta.node_fields.length;
	const edgeStride = meta.edge_fields.length;
	const typeAt = meta.node_fields.indexOf("type");
	const nameAt = meta.node_fields.indexOf("name");
	const sizeAt = meta.node_fields.indexOf("self_size");
	const edgeCountAt = meta.node_fields.indexOf("edge_count");
	const edgeTypeAt = meta.edge_fields.indexOf("type");
	const edgeNameAt = meta.edge_fields.indexOf("name_or_index");
	const edgeToAt = meta.edge_fields.indexOf("to_node");
	const nodeTypes = meta.node_types[typeAt];
	const edgeTypes = meta.edge_types[edgeTypeAt];
	if (!Array.isArray(nodeTypes) || !Array.isArray(edgeTypes) || [typeAt, nameAt, sizeAt, edgeCountAt, edgeTypeAt, edgeNameAt, edgeToAt].some(offset => offset < 0)) throw new Error("Unsupported Bun snapshot metadata");
	const nodes = snapshot.nodes;
	const edges = snapshot.edges;
	const classes: Record<string, Aggregate> = {};
	const targets: number[] = [];
	const nodeLabel = (offset: number): string => {
		const type = nodeTypes[nodes[offset + typeAt]];
		if (type === "string") return "(string)";
		const name = snapshot.strings[nodes[offset + nameAt]];
		return /^[A-Za-z_$][A-Za-z0-9_$ /()#.-]{0,120}$/.test(name) ? `${type}:${name}` : `(${type})`;
	};
	for (let offset = 0; offset < nodes.length; offset += nodeStride) {
		const label = nodeLabel(offset);
		const aggregate = classes[label] ??= { count: 0, bytes: 0 };
		aggregate.count++;
		aggregate.bytes += nodes[offset + sizeAt];
		if (/Uint8Array|ArrayBuffer|InteractiveMode|TUI$|AgentSession|Map$|Set$|Array$/.test(label)) targets.push(offset);
	}
	targets.sort((a, b) => nodes[b + sizeAt] - nodes[a + sizeAt]);
	const counts = new Map<string, number>();
	const selected = targets.filter(offset => {
		const label = nodeLabel(offset);
		const count = counts.get(label) ?? 0;
		counts.set(label, count + 1);
		return count < 24;
	});
	const heads = new Int32Array(snapshot.snapshot.node_count).fill(-1);
	const parents = new Int32Array(snapshot.snapshot.edge_count);
	const next = new Int32Array(snapshot.snapshot.edge_count);
	let edgeOffset = 0;
	for (let nodeOffset = 0; nodeOffset < nodes.length; nodeOffset += nodeStride) {
		const count = nodes[nodeOffset + edgeCountAt];
		for (let index = 0; index < count; index++, edgeOffset += edgeStride) {
			if (edgeTypes[edges[edgeOffset + edgeTypeAt]] === "weak") continue;
			const edgeIndex = edgeOffset / edgeStride;
			const toIndex = edges[edgeOffset + edgeToAt] / nodeStride;
			parents[edgeIndex] = nodeOffset;
			next[edgeIndex] = heads[toIndex];
			heads[toIndex] = edgeIndex;
		}
	}
	const safeProperties: Record<string, true> = { root: true, global: true, this: true, session: true, agent: true, settings: true, modelRegistry: true, authStorage: true, buffer: true, data: true, state: true, value: true, key: true, entries: true, listeners: true, _events: true, callback: true, context: true, handler: true, listener: true, _onTimeout: true, prototype: true, constructor: true, stdout: true, stderr: true, stdin: true, stream: true, reader: true, writer: true };
	const findPath = (target: number): PathEntry[] => {
		const queue = [target];
		const visited = new Set<number>(queue);
		const towardTarget = new Map<number, { child: number; edge: number }>();
		let root: number | undefined;
		for (let cursor = 0; cursor < queue.length; cursor++) {
			const current = queue[cursor];
			if (current === 0 || nodeTypes[nodes[current + typeAt]] === "synthetic") { root = current; break; }
			for (let edge = heads[current / nodeStride]; edge >= 0; edge = next[edge]) {
				const parent = parents[edge];
				if (visited.has(parent)) continue;
				visited.add(parent);
				towardTarget.set(parent, { child: current, edge });
				queue.push(parent);
			}
		}
		if (root === undefined) return [{ node: "(no root found within search bound)" }, { node: nodeLabel(target) }];
		const result: PathEntry[] = [{ node: nodeLabel(root) }];
		let current = root;
		while (current !== target && result.length < 32) {
			const step = towardTarget.get(current);
			if (!step) break;
			const offset = step.edge * edgeStride;
			const edgeType = edgeTypes[edges[offset + edgeTypeAt]];
			const name = edgeType === "element" ? "element" : snapshot.strings[edges[offset + edgeNameAt]];
			result.push({ node: nodeLabel(step.child), edge: safeProperties[name] || /^[A-Za-z_$#][A-Za-z0-9_$#.-]{0,80}$/.test(name ?? "") ? name : `(${edgeType})` });
			current = step.child;
		}
		return result;
	};
	return {
		at: new Date().toISOString(), stage,
		nodeCount: snapshot.snapshot.node_count, edgeCount: snapshot.snapshot.edge_count, classes,
		largest: selected.map(offset => ({ node: nodeLabel(offset), bytes: nodes[offset + sizeAt], path: findPath(offset) })),
	};
}
